import{_ as o,a0 as p,w as l,s as d,I as s,x as t,a1 as a,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"掌握強大的 Git 變基命令 | LCTT x X-CMD","titleTemplate":false,"description":"掌握強大的 Git 變基命令 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"掌握強大的 Git 變基命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"掌握強大的 Git 變基命令 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221121.2 ⭐️⭐️ Learn Git 3 commands to level up your skill","title":"掌握強大的 Git 變基命令","tag":"202212","desc":""},"relativePath":"202212/20221121.2 ⭐️⭐️ Learn Git 3 commands to level up your skill.md","filePath":"[post].md"}'),c={name:"202212/20221121.2 ⭐️⭐️ Learn Git 3 commands to level up your skill.md"};function g(u,e,b,m,h,k){const i=p("Link");return l(),d("div",null,[e[26]||(e[26]=s("h1",{id:"掌握強大的-git-變基命令",tabindex:"-1"},[t("掌握強大的 Git 變基命令 "),s("a",{class:"header-anchor",href:"#掌握強大的-git-變基命令","aria-label":"Permalink to “掌握強大的 Git 變基命令”"},"​")],-1)),e[27]||(e[27]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202212/07/133637yq2526zsp7f1t7a2.jpg",alt:""})],-1)),e[28]||(e[28]=s("blockquote",null,[s("p",null,"學習如何使用 Git 來壓扁、變基和精選。")],-1)),s("p",null,[e[1]||(e[1]=t("當我與別人談到 Git 時，幾乎每個人都對 ",-1)),a(i,{href:"https://opensource.com/article/20/4/git-rebase-i"},{default:n(()=>[...e[0]||(e[0]=[t("git rebase 命令",-1)])]),_:1}),e[2]||(e[2]=t(" 有強烈的印象，這個命令讓許多人遇到了問題，而不得不更改目錄、刪除倉庫、然後再重新克隆一個倉庫。我認為這是因為他們誤解了分支是如何工作，遇到了一個非常糟糕的默認界面，還有一些合併衝突把事情搞得一團糟。",-1))]),e[29]||(e[29]=r(`<h3 id="怎麼找不到-git-squash-命令" tabindex="-1">怎麼找不到 git squash 命令？ <a class="header-anchor" href="#怎麼找不到-git-squash-命令" aria-label="Permalink to “怎麼找不到 git squash 命令？”">​</a></h3><p>如果你曾在本地的倉庫提交過很多次，並希望能把這些提交都合併為一個提交，接下來，我們就來介紹能用什麼 Git 命令達到這個目的。Git 稱這個概念為 “<ruby>壓扁提交<rt> squash commits </rt></ruby>”。我在編寫文檔時發現了這個概念：我花了十幾個提交才修改好我的 Markdown 文檔，但是倉庫的維護者不想看到我的所有嘗試，以免擾亂了該項目的歷史，所以我被告知“需要壓扁你的提交”。</p><p><strong>壓扁提交</strong>聽起來是一個很有用的方法。但是隻有一個問題：我不知道該怎麼做。作為 Git 的新手，我做了任何人會做的事情：我去查閲 <code>git-squash</code> 的手冊，但我立即遇到了阻礙：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man git-squash</span></span>
<span class="line"><span>&gt; No manual entry for git-squash</span></span></code></pre></div>`,4)),s("p",null,[e[4]||(e[4]=t("我發現沒有一個名為 ",-1)),e[5]||(e[5]=s("code",null,"squash",-1)),e[6]||(e[6]=t(" 的 Git 命令，而是被要求 ",-1)),a(i,{href:"https://opensource.com/article/22/4/manage-git-commits-rebase-i-command"},{default:n(()=>[...e[3]||(e[3]=[t("運行一個完全獨立的命令：git rebase 命令",-1)])]),_:1}),e[7]||(e[7]=t("，該命令能將我的所有提交最終合併為一個提交。",-1))]),e[30]||(e[30]=r(`<p>我知道我碰到一個常見的情形：已經使用工具一段時間的人使用了<strong>行話</strong>或引用了一個概念，這個概念對他們來説是非常清楚的，但對新手來説就不能明白了。從概念上講，這個情況看起來是這樣的：</p><p><img src="https://opensource.com/sites/default/files/2022-11/gitbeyond2.spices.png" alt="Image of 6 bowls of different colored spices, and an arrow pointing to the second image of all the spices blended into one bowl."></p><p>我這樣説是為了鼓勵你，你絕對不是第一個或最後一個 <em>被 Git 或談論 Git 的人</em> 弄糊塗的人。你可以要求對方説明白他的意見，並幫助你應該使用的正確命令。倉庫的維護者實際上的意思是，“使用 <code>git rebase</code> 命令**，將很多提交壓扁成一個提交”。</p><h3 id="現在就來學習-git-rebase-命令吧" tabindex="-1">現在就來學習 git rebase 命令吧 <a class="header-anchor" href="#現在就來學習-git-rebase-命令吧" aria-label="Permalink to “現在就來學習 git rebase 命令吧”">​</a></h3><p><code>git rebase</code> 命令會將一個提交鏈從其第一個父級中刪除，並將其放置在另一個提交鏈的末尾，將兩個提交鏈組合成一個長鏈，而不是兩個並行鏈。我意識到這是一個很複雜的定義。</p><p>回想一下 Git 的提交是如何鏈接在一起的，你可以看到，除了初始的 <code>main</code>（或 <code>master</code>）分支外，任何分支都有一個 <ruby>父提交<rt> parent commit </rt></ruby> 作為該鏈的 “<ruby>基礎<rt> base </rt></ruby>”。“<ruby>變基<rt> rebase </rt></ruby>” 能使另一個鏈中的最後一個提交成為指定分支的新 “<ruby>基礎提交<rt> base commit </rt></ruby>”。</p><p>在 Git 中整合來自不同分支的修改主要有兩種方法：<ruby>合併<rt>merge</rt></ruby> 以及 <ruby>變基<rt>rebase</rt></ruby>，你可能更熟悉 <code>git merge</code> 命令。接下來，就來看看 [git-scm.com] 是如何解釋 <code>git merge</code> 和 <code>git rebase</code> 的差異：</p><p><img src="https://opensource.com/sites/default/files/2022-11/gitbeyond2.gitmerger.png" alt="Image of Git merge versus git rebase shown as numbered bubbles."></p><p>在合併示例中，它會把兩個分支的最新快照（<code>C3</code> 和 <code>C4</code>）以及二者最近的共同祖先（<code>C2</code>）進行三方合併，合併的結果是生成一個新的快照（<code>C5</code>）。<code>experiment</code> 的分支指針仍然存在，仍然指向 <code>C4</code>。</p><p>在變基示例中，它提取在 <code>C4</code> 中引入的補丁和修改，然後在 <code>C3</code> 的基礎上應用一次，使 <code>C3</code> 成為 <code>C4</code> 的新父級，併產生了一個名為 <code>C4&#39;</code> 的新提交。</p><p>（LCTT 譯註：具體的命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout experiment</span></span>
<span class="line"><span>$ git rebase main</span></span>
<span class="line"><span>First, rewinding head to replay your work on top of it...</span></span>
<span class="line"><span>Applying: added staged command</span></span></code></pre></div><p>它的原理是首先找到這兩個分支 —— 即當前分支 <code>experiment</code>、變基操作的目標基底分支 <code>main</code> —— 的最近共同祖先 <code>C2</code>，然後對比當前分支相對於該祖先的歷次提交，提取相應的修改並存為臨時文件，然後將當前分支指向目標基底 <code>C3</code>，最後以此將之前另存為臨時文件的修改依序應用。）</p><p>值得注意的是，分支指針 <code>main</code> 沒有移動。要讓 Git 將指針移動到鏈的末尾（由<code>experiment</code> 指向），你還需要執行合併。</p><p>（LCTT 譯註：具體的命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout main</span></span>
<span class="line"><span>$ git merge experiment</span></span></code></pre></div><p><img src="https://www.progit.cn/images/basic-rebase-4.png" alt="master 分支的快進合併"></p><p>此時，<code>C4&#39;</code> 指向的快照就和上面使用 <code>merge</code> 命令的例子中 <code>C5</code> 指向的快照一模一樣了。）</p><p><code>git rebase</code> 並不能替代 <code>git merge</code>。<code>git rebase</code> 是一種用於製作更清晰的歷史記錄，以與 <code>git merge</code> 結合使用的工具。</p><p>（LCTT 譯註：使用 <code>git rebase</code> 命令將提交到某一分支上的所有修改都移至另一分支上，就好像“重新播放”一樣。）</p><h4 id="交互式變基能給你一個更友好的界面" tabindex="-1">交互式變基能給你一個更友好的界面！ <a class="header-anchor" href="#交互式變基能給你一個更友好的界面" aria-label="Permalink to “交互式變基能給你一個更友好的界面！”">​</a></h4><p>從命令列執行 <code>git rebase</code> 命令，最可怕的地方在於它<strong>糟糕的默認界面</strong>。運行命令 <code>git rebase &lt;target-refr&gt;</code> 要麼有效，要麼會變得一團糟，因為它沒有太多的反饋或方法來確保它做你想做的事情。幸運的是，<code>git rebase</code> 命令和許多其他 Git 命令一樣，具有 <ruby>交互模式<rt> interactive mode </rt></ruby>，你可以使用參數 <code>-i</code> 或者 <code>-interactive</code> 來使用交互模式。</p><p><img src="https://opensource.com/sites/default/files/2022-11/gitbeyond2.GitLens%20Interactive%20Rebase%20tool%20in%20VS%20Code.png" alt="Image of the Git lens interactive Rebase tool in VS Code."></p><p>在使用交互式模式時，<code>git rebase</code> 會從一個糟糕的黑框界面轉換為一個<strong>選項菜單</strong>，允許你選擇對正在變基的提交鏈所做的事。對於每個提交，你可以<strong>選擇</strong>：</p><ul><li><ruby>選用<rt>pick</rt></ruby>：按原樣包含</li><li><ruby>重寫<rt>reword</rt></ruby>：重寫提交消息</li><li><ruby>編寫<rt>edit</rt></ruby>：在變基完成之前對提交中的文件進行進一步更改</li><li><ruby>壓扁<rt>squash</rt></ruby>：將多個提交壓縮成一個提交，保留所有提交消息</li><li><ruby>修理<rt>fixup</rt></ruby>：將多個提交壓縮成一個提交，但只保留最後一個提交消息</li><li><ruby>丟棄<rt>drop</rt></ruby>：丟棄此提交</li></ul>`,25)),s("p",null,[e[9]||(e[9]=t("就我個人而言，我更喜歡 ",-1)),a(i,{href:"https://marketplace.visualstudio.com/items?itemName=eamodio.gitlens"},{default:n(()=>[...e[8]||(e[8]=[t("VS Code 的開源 GitLens 擴展",-1)])]),_:1}),e[10]||(e[10]=t(" 使用下拉選擇列表佈局選項的方式，但 Git 允許你使用任何編輯器選擇這些選項。對於 Emacs 或 Vim 等純文本工具，你需要鍵入選擇，而不是從菜單中選擇，但最終結果仍然是相同的。",-1))]),e[31]||(e[31]=r(`<h4 id="何時做變基" tabindex="-1">何時做變基 <a class="header-anchor" href="#何時做變基" aria-label="Permalink to “何時做變基”">​</a></h4><p>知道 <em>何時</em> 做變基與知道 <em>如何</em> 做變基同樣重要。事實上，如果你不在乎你的倉庫歷史提交消息有點混亂的話，那麼你可以永遠都不使用 <code>git rebase</code> 命令。但是，如果你想要更乾淨的歷史提交消息，並且想要更少擾亂你的圖形視圖的提交，那麼當你使用 <code>git rebase</code> 命令時，有一個重要的<strong>經驗法則</strong>需要時刻記住：</p><blockquote><p>“不要變基你存儲庫以外的的提交，那些提交可能是別人工作的基礎。”</p></blockquote><p>如果你遵循該準則，不會發生什麼大問題的。</p><p>簡而言之，如果你讓一個<strong>本地分支</strong>來完成你的工作，變基是沒有問題的。但一旦該分支被 <ruby>推送 <rt> push </rt></ruby> 了，就不要再變基該分支了。當然，你想要怎麼做完全取決於你自己。</p><p>希望你會認為上述內容有助於你理解 <code>git rebase</code> 命令的工作原理，並能讓你更有信心地使用它。與任何 Git 命令一樣，<strong>練習</strong>是學習和理解怎麼做的唯一方法。我鼓勵你勇敢地嘗試 <ruby>交互式變基<rt> interactive rebase </rt></ruby> <code>git rebase -i &lt;branch name&gt;</code>！</p><h3 id="接下來學習-git-cherry-pick-命令吧" tabindex="-1">接下來學習 Git cherry-pick 命令吧 <a class="header-anchor" href="#接下來學習-git-cherry-pick-命令吧" aria-label="Permalink to “接下來學習 Git cherry-pick 命令吧”">​</a></h3><p>大多數開發人員將修改提交到某一分支上，但是之後發現他們一直<strong>提交到了錯誤的分支上</strong>。理想情況下，他們可以拿走那個提交，然後把它移到正確的分支，這正是 <code>git cherry-pick</code> 命令的作用。</p><p><code>git cherry-pick</code> 命令利用了變基單個提交的方法。這一用法非常常見，以至於有了它自己的命令。</p><p><img src="https://opensource.com/sites/default/files/2022-11/gitbeyond2.cherrypicking.png" alt="Image of a woman picking a cherry from one tree and putting on another tree."></p><p>要使用 <code>git cherry-pick</code>，你只需告訴 Git 你要移動到“那個分支”的提交 ID（由 <code>HEAD</code> 指向）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick &lt;target-ref&gt;</span></span></code></pre></div><p>如果出現問題，你可以根據 Git 提供的錯誤消息，來進行恢復：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick -i 2bc01cd</span></span>
<span class="line"><span>Auto-merging README.md</span></span>
<span class="line"><span>CONFLICT (content): Merge conflict in README.md</span></span>
<span class="line"><span>error: could not apply 2bc01cd… added EOF lines</span></span>
<span class="line"><span>hint: After resolving the conflicts, mark them with</span></span>
<span class="line"><span>hint: &quot;git add/rm &quot;, then run</span></span>
<span class="line"><span>hint: &quot;git cherry-pick --continue&quot;.</span></span>
<span class="line"><span>hint: You can instead skip this commit with &quot;git cherry-pick --skip&quot;.</span></span>
<span class="line"><span>hint: To abort and get back to the state before &quot;git cherry-pick&quot;,</span></span>
<span class="line"><span>hint: run &quot;git cherry-pick --abort&quot;.</span></span>
<span class="line"><span>$ git cherry-pick --abort</span></span></code></pre></div><h3 id="讓-git-更強大" tabindex="-1">讓 Git 更強大 <a class="header-anchor" href="#讓-git-更強大" aria-label="Permalink to “讓 Git 更強大”">​</a></h3><p><code>git rebase</code> 命令是 Git 實用程序強大的地方之一。你最好在測試倉庫中先練習一下怎麼使用，一旦你熟悉了它的概念和工作流程，你就可以給倉庫一個清晰歷史消息記錄了。</p><hr>`,17)),s("p",null,[e[12]||(e[12]=t("via: ",-1)),a(i,{href:"https://opensource.com/article/22/11/advanced-git-commands"},{default:n(()=>[...e[11]||(e[11]=[t("https://opensource.com/article/22/11/advanced-git-commands",-1)])]),_:1})]),s("p",null,[e[17]||(e[17]=t("作者：",-1)),a(i,{href:"https://opensource.com/users/dwaynemcdaniel"},{default:n(()=>[...e[13]||(e[13]=[t("Dwayne McDaniel",-1)])]),_:1}),e[18]||(e[18]=t(" 選題：",-1)),a(i,{href:"https://github.com/lkxed"},{default:n(()=>[...e[14]||(e[14]=[t("lkxed",-1)])]),_:1}),e[19]||(e[19]=t(" 譯者：",-1)),a(i,{href:"https://github.com/chai001125"},{default:n(()=>[...e[15]||(e[15]=[t("chai001125",-1)])]),_:1}),e[20]||(e[20]=t(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[16]||(e[16]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[23]||(e[23]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[21]||(e[21]=[t("LCTT",-1)])]),_:1}),e[24]||(e[24]=t(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...e[22]||(e[22]=[t("Linux中國",-1)])]),_:1}),e[25]||(e[25]=t(" 榮譽推出",-1))])])}const T=o(c,[["render",g]]);export{C as __pageData,T as default};
